class Rea < Formula
  desc "Analyze binaries through the REA evidence engine"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/rea-0.3.0/rea-0.3.0-darwin-universal.xz",
    linux: on_arch_conditional(
      arm:   "https://github.com/qzmfranklin/homebrew-tap/releases/download/rea-0.3.0/rea-0.3.0-linux-arm64.xz",
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/rea-0.3.0/rea-0.3.0-linux-amd64.xz",
    ),
  )
  version "0.3.0"
  sha256 on_system_conditional(
    macos: "a9ecd88616b298ac47bc04f3587469c159d911f17615c4ea8ca17d58fdfe558f",
    linux: on_arch_conditional(
      arm:   "c8089b3b97fe55d93741774d0cd6db2375ab9b06adc56ea0323cdb093dac0b1c",
      intel: "dd0be24326bd738cae56fd6e49c239d6094e544ce03e1c65e07c733cf1f198bb",
    ),
  )
  license :cannot_represent

  def install
    # The asset is the BINARY ITSELF, xz'd by brew_artifact — the
    # single-file form (rules_brew plan 0006: a lone binary ships as bare .xz,
    # never a one-file tarball). Homebrew stages a bare .xz download
    # DECOMPRESSED under the ASSET name — the version-suffixed
    # rea-{version}-{os}-{arch}, not `rea` — so glob it and install under the
    # canonical command name.
    bin.install Dir["rea-*"].first => "rea"

    # chmod first, UNCONDITIONALLY: a bare .xz carries no mode bits, so the
    # decompressed binary lands 0644 and every later step that execs it gets
    # EACCES on linux (the yag 0.18.0 linux tap install failed exactly here —
    # the M6-found defect; the tar-form products never saw it). Homebrew also
    # stages files read-only, and both xattr and codesign need to WRITE to the
    # binary (xattr fails with EACCES otherwise).
    chmod 0755, bin/"rea"

    # Ad-hoc codesign on macOS. This formula sets adhoc_sign = False and owns
    # the block HERE (the klash precedent) because the completion stanza below
    # EXECUTES the binary: the renderer splices this snippet BEFORE its own
    # generated codesign lines, and a cross-built arm64 Mach-O is unsigned
    # until signed — macOS kills the exec, so the sign must come first. This
    # is INTENTIONAL and load-bearing, not a workaround: the binary is
    # unsigned, and macOS refuses to exec an unsigned or stale-signed Mach-O;
    # writing the file also invalidates any prior signature, so it must be
    # re-signed after install.
    if OS.mac?
      system "/usr/bin/xattr", "-cr", bin/"rea"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"rea"
    end

    # Completion scripts installed WITH the binary (plan
    # modules/rules_native/plan/0003-04 row 4.3, the operator's ruling):
    # rea's hidden `complete` subcommand writes the requested shell's
    # script to STDOUT and edits nothing — a bare positional, no `--print`
    # flag — so the macro's built-in completions attr (hardwired to the
    # `complete --print <shell>` invocation the yag/klash/iap CLIs use) does
    # not fit rea and the stanza lives here instead.
    generate_completions_from_executable(
      bin/"rea",
      "complete",
      shells: [:bash, :zsh, :fish],
    )
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/rea"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew rea at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed rea is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"rea") unless linked.symlink?
  end


  def caveats
    on_linux do
      <<~EOS
        rea's linux binary is fully static (musl) — no glibc requirement; it
        runs on any linux the kernel supports. No interpreter, no shared
        libraries: the single binary is the whole install, on any distribution
        however old. The formula carries no dependencies on any host, so plain
        `brew install rea` works everywhere.
      EOS
    end
  end

  test do
    # rea answers --version (no `version` subcommand), so the renderer's
    # default version-check test would invoke a nonexistent command; the help
    # probe asserts the CLI answers without touching the engine.
    assert_match version.to_s, shell_output("#{bin}/rea --version")
    assert_match(/Usage: rea/, shell_output("#{bin}/rea --help"))
  end
end
